# Community/CRISPRfinder standard scoring for a 24bp region:
# positions 1-12 vs 13-24 (symmetry 12-12), plus extra checks on 1-3 and 10-12 with 2bp spacer
def p5(sub):
    p=0.0
    for i in range(12):
        if sub[i]==sub[23-i]: p+=2
        else: p += (-1 if (sub[i] in 'GC' and sub[23-i] in 'GC') else 0.5)
    for i in range(2):
        p += 1 if sub[i]==sub[i+2] else -1
        p += 1 if sub[9+i]==sub[11+i] else -1
    return p

# collect candidate repeat segments and generalize by merging identical core regions
scores=[]
for s in range(n-29):
    sc=p5(seq[s:s+24])
    if sc>=6: scores.append((sc,s))
print('candidate windows with p5>=6:', len(scores))
# merge overlapping into candidate DR candidates by picking local maxima
scores.sort(key=lambda x:(-x[0], x[1]))
kept=[]
used=sorted(scores)
removed=set()
for sc,s in used:
    if s in removed: continue
    kept.append((sc,s))
    for sc2,s2 in used:
        if abs(s-s2)<12: removed.add(s2)
print('distinct candidates:',len(kept))
# for each candidate try the first 32bp as repeat, find up to 1-mismatch copies
