def get_pairs(inverted):
    out = []
    for shift in range(K, 1000):
        for i in range(n-shift-K):
            left = seq[i:i+K]
            right = seq[i+shift:i+shift+K]
            if inverted:
                right = right[::-1].translate(comp)
            if left == right:
                out.append((i, i+shift))
