def merge_runs(pairs):
    runs = []
    for a, b in pairs:
        best = None
        for idx, r in enumerate(runs):
            if (a, b) == (r[0]+1, r[1]+1):
                best = idx
        if best is not None:
            ra, rb, rl = runs[best]
            runs[best] = (a, b, rl+1)
        else:
            runs.append((a, b, K))
    return runs

